-- Create "usage_logs" table
CREATE TABLE "usage_logs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "api_key_id" bigint NULL, "user_id" bigint NULL, "model_id" character varying NOT NULL, "prompt_tokens" bigint NOT NULL DEFAULT 0, "completion_tokens" bigint NOT NULL DEFAULT 0, "total_tokens" bigint NOT NULL DEFAULT 0, "prompt_audio_tokens" bigint NULL DEFAULT 0, "prompt_cached_tokens" bigint NULL DEFAULT 0, "prompt_write_cached_tokens" bigint NULL DEFAULT 0, "prompt_write_cached_tokens_5m" bigint NULL DEFAULT 0, "prompt_write_cached_tokens_1h" bigint NULL DEFAULT 0, "completion_audio_tokens" bigint NULL DEFAULT 0, "completion_reasoning_tokens" bigint NULL DEFAULT 0, "completion_accepted_prediction_tokens" bigint NULL DEFAULT 0, "completion_rejected_prediction_tokens" bigint NULL DEFAULT 0, "source" character varying NOT NULL DEFAULT 'api', "format" character varying NOT NULL DEFAULT 'openai/chat_completions', "total_cost" double precision NULL, "cost_items" jsonb NULL, "cost_price_reference_id" character varying NULL, "channel_id" bigint NULL, "project_id" bigint NOT NULL DEFAULT 1, "request_id" bigint NOT NULL, PRIMARY KEY ("id"));
-- Create index "usage_logs_by_api_key_id_created_at" to table: "usage_logs"
