-- Create "users" table
CREATE TABLE "users" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "deleted_at" bigint NOT NULL DEFAULT 0, "email" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'activated', "prefer_language" character varying NOT NULL DEFAULT 'en', "password" character varying NOT NULL, "first_name" character varying NOT NULL DEFAULT '', "last_name" character varying NOT NULL DEFAULT '', "avatar" character varying NULL, "is_owner" boolean NOT NULL DEFAULT false, "scopes" jsonb NULL, PRIMARY KEY ("id"));
